import{_ as s,o as t,c as o,a2 as n}from"./chunks/framework.C3idr2hZ.js";const a="/orc/screens/activity-session-rows.png",i="/orc/screens/session-cache.png",r="/orc/screens/session-lineage-desktop.png",f=JSON.parse('{"title":"Live agent sessions","description":"","frontmatter":{},"headers":[],"relativePath":"docs/live-sessions.md","filePath":"docs/live-sessions.md","lastUpdated":1794603748000}'),d={name:"docs/live-sessions.md"};function c(h,e,l,p,u,g){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="live-agent-sessions" tabindex="-1">Live agent sessions <a class="header-anchor" href="#live-agent-sessions" aria-label="Permalink to &quot;Live agent sessions&quot;">​</a></h1><p>The Sessions view uses the same working, waiting and ended states, task links, search and conversation viewer for all agents. Waiting sessions stay in the active view; inactivity alone does not end a registered session.</p><p>Opening a linked task keeps you on that task even while a session search is updating.</p><p>Sessions without a title use a readable folder name, including Windows extended paths, network shares, file URLs and POSIX paths. For example, <code>\\\\?\\C:\\Projects\\orc</code> displays as <code>orc</code> rather than the full path in session and notification titles. Named sessions keep their titles; execution uses the original folder path. Codex uses the first prompt when its native title is only the folder.</p><h2 id="rename-hide-and-fork" tabindex="-1">Rename, hide and fork <a class="header-anchor" href="#rename-hide-and-fork" aria-label="Permalink to &quot;Rename, hide and fork&quot;">​</a></h2><p>A session&#39;s own menu, <strong>Rename</strong>, stores your name on the ORC row. The agent&#39;s title still updates underneath, and <strong>Use agent title</strong> in the rename dialog drops the override, so a re-sync never resurrects a name you removed. <strong>Hide</strong> keeps the session and its transcript and only removes it from the default list; <strong>Show hidden</strong> in the filters brings hidden rows back with a <strong>Hidden</strong> label, and <strong>Show</strong> in the same menu restores one. Both survive a restart and a session re-sync. Hiding does not mute notifications, tasks or terminals that already point at the session.</p><p><strong>Fork in terminal</strong> starts a new native session from the session&#39;s history when the agent CLI supports it: Claude runs <code>claude --resume &lt;id&gt; --fork-session</code> and Pi runs <code>pi --fork &lt;id&gt;</code>. The fork is a new terminal and a new session row, and the original conversation is not touched. Codex, Cursor, Gemini, OpenCode and agents without a CLI fork do not offer the action; fork those conversations from an assistant response in chat instead, which uses the agent&#39;s native session fork or a bounded context replay.</p><p>Activity and full-width session history share compact title/provider/state rows. An ORC terminal agent without observed session activity shows <strong>Unknown</strong>, rather than assuming it is idle. A session&#39;s working folder decides its project: the most specific project folder wins, and a worktree resolves to its shared checkout even when it lives outside the project&#39;s folder. Opening a session from the session list adopts its project in the workspace header, so the session list and notification inbox follow the project you are actually working in. The mapping is re-evaluated when project folders change, and live sessions and their notifications move with them; a session whose project folder was moved away stops claiming the old project. Each project has one folder scope. Worktrees resolve to their shared checkout, and a project without a scope takes the repository roots of its known sessions as derived folders, so no second folder list is stored. OpenCode&#39;s session store is watched alongside the other agent stores, so its new sessions appear without waiting for another agent&#39;s activity.</p><p><img src="'+a+'" alt="Compact Activity session rows with demo data"></p><p>Open a Codex or Claude session to see its last reported cached-input percentage. Expand that compact row for input, cached reads, cache writes when reported, and recorded session totals. Cached input is a share of <strong>input</strong> tokens, not output or total billed cost. Claude input includes uncached input plus cache reads and writes; Codex reports input with its cache reads already included. Claude totals deduplicate repeated messages; Codex totals use the provider&#39;s cumulative snapshot.</p><p>When Claude records a cache-write lifetime and activity timestamp, the indicator can change to <strong>Cache may need rebuilding</strong> after that lifetime has elapsed since the recorded activity. This is a conservative hint, not an exact expiry or a guarantee about the next request: request generation time, prompt changes and other requests can affect reuse. Missing cache metrics or timing are omitted; there is no expiry-unavailable message. Codex does not currently provide timing evidence here. Other backends omit the indicator until native cache metrics are supported. Metrics refresh every 15 seconds while an active session&#39;s details are open; opening an ended session reads its recorded data once.</p><p><img src="'+i+`" alt="Session cache details with demo data"></p><p>Codex uses its native writer locks and latest turn status. A held lock identifies an open session; a completed turn is waiting, and a turn in progress is working. A released lock ends the session. Older Codex versions without a writer-lock directory retain the legacy activity fallback.</p><p>Cursor IDE history, Cursor CLI (<code>agent</code> / <code>cursor-agent</code>) history and Gemini conversations are discovered separately. CLI and IDE Cursor histories are separate stores: only Cursor CLI records offer a CLI resume command. Gemini and Cursor CLI support Resume in a terminal, Copy resume command, and Copy terminal link alongside Claude and Codex.</p><p>OpenCode sessions are read from its SQLite store (<code>~/.local/share/opencode/opencode.db</code>) on the local machine or the selected SSH host. Top-level sessions appear with their folder, title and token count; the conversation viewer shows messages, reasoning and tool calls with their output. OpenCode has no lifecycle hooks, so its sessions are listed as ended. Resume opens <code>opencode --session &lt;id&gt;</code> in a terminal, and ended OpenCode sessions also appear in the chat history list, where opening one imports its transcript and continues the same session in chat.</p><p>Pi 1.5.2+ sessions are discovered from the native <code>~/.pi/agent/sessions</code> JSONL store on the selected execution host. Absolute <code>PI_CODING_AGENT_DIR</code> paths in Pi provider environment settings (and the local server environment) are also scanned under their <code>sessions</code> directory. The viewer follows the active branch and context edits and shows text, reasoning, tool calls/results and image placeholders. Native names and recorded token totals are retained. External Pi sessions appear as ended because Pi has no lifecycle hook registration. Close the native Pi conversation before resuming it in ORC to avoid concurrent writers.</p><p>Resume in chat imports the visible history and continues the original Pi UUID in its original folder and execution host. It uses the enabled default Pi provider, the enabled built-in Pi provider, or the sole enabled Pi provider, in that order. If several named Pi providers are enabled, choose the intended one as the default first. Native history is not replayed as a new prompt. Terminal resume uses <code>pi --session &lt;uuid&gt;</code>. Custom <code>--session-dir</code> stores outside these directories, older session formats, cross-host handoff and embedding/archive ingestion are not supported for Pi.</p><p>A Claude permission prompt, Claude question, or Gemini tool-permission prompt sets that session to <strong>Waiting for you</strong> within a few seconds of the hook firing. ORC sends one browser push on the attention topic for that transition. Answering the prompt, or the turn ending, clears the flag. A session that stays waiting does not send another push. Codex questions continue to come from its transcript. OpenCode chat questions use the same question card and waiting state even though discovered OpenCode sessions still show as ended. Cursor&#39;s installed hooks do not include a permission event, so Cursor waits are unchanged.</p><p>Install lifecycle hooks for Claude, Cursor and Gemini from this checkout:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bun scripts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">install-session</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hooks.ts</span></span></code></pre></div><p>The installer preserves existing hook entries and other settings, makes dated backups, and adds lifecycle events to <code>~/.claude/settings.json</code>, <code>~/.cursor/hooks.json</code> and <code>~/.gemini/settings.json</code>. Claude gains permission, notification, question and stop hooks. Gemini gains the notification hook beside its existing lifecycle events. New/resumed sessions register their owner PID in <code>~/.orc/live-sessions/</code>. Start, prompt, response, tool and stop hooks update the shared state; session-end hooks and dead owner processes end it. Existing sessions may need to resume or reload hooks once before they register. Hook-captured conversations begin when hooks are installed; old native history is retained when its transcript exists.</p><p>Hooks need Bun on the installation machine. They run a bounded owner lookup, write private local registry/transcript files, and never grant tool permissions or inject prompts. Native agent transcripts remain read-only. Full prompt/tool content belongs to the local conversation history and is not sent to external services by these hooks.</p><p>Other local agents can use <code>LiveRegistration</code>, <code>readRegistrations</code> and <code>writeRegistration</code> from <code>@orc/core/live-session</code> to participate in the same PID-backed lifecycle. Native discovery/resume commands still require a supported adapter; the dashboard automatically includes registered backend names in its filter.</p><h2 id="sending-a-message-to-a-session" tabindex="-1">Sending a message to a session <a class="header-anchor" href="#sending-a-message-to-a-session" aria-label="Permalink to &quot;Sending a message to a session&quot;">​</a></h2><p>Open a session and use <strong>Send message</strong> to queue a note for it. ORC delivers queued notes at the session&#39;s next safe point: before a tool call, at a prompt submit or stop hook, or when the agent reports session start. For an ended session, ORC resumes it with a bounded turn. Messages wait in a compact queue you can reorder or cancel until delivery starts. A delivered message records whether it arrived through a native hook (<code>hook</code>), an ORC chat turn (<code>chat</code>), a resume (<code>resume</code>) or native steering into a running chat turn (<code>steer</code>).</p><p>Live sessions of agents without a context-capable hook (for example Cursor or OpenCode) cannot receive a message while they are running; queue it after the session ends. Claude, Codex and Gemini sessions accept messages through their installed hooks and the ORC-managed Claude SDK hook.</p><p>Delivery is not approval. ORC tells the recipient the message came from another session or a human relay, that it cannot approve a tool, permission, plan or configuration change, and that configuration must be changed by a human. An agent-to-agent message chain ends after three hops, and one agent session may queue at most 20 messages per target in a rolling hour. Pass a stable <code>request_id</code> when retrying the same send. Messages still delivering when ORC restarts become <code>interrupted</code> and are never retried; queued messages remain queued.</p><p>The same queue is available to agents through the <code>session_send</code> MCP tool (bind the connection with <code>?session=&lt;session id&gt;</code> or run stdio MCP inside the agent) and to chat channels with <code>/send &lt;session id&gt; &lt;message&gt;</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/send                  list live sessions</span></span>
<span class="line"><span>/send &lt;id&gt;            choose a target</span></span>
<span class="line"><span>/send &lt;id&gt; Fix the failing test</span></span></code></pre></div><h2 id="delegating-to-other-sessions" tabindex="-1">Delegating to other sessions <a class="header-anchor" href="#delegating-to-other-sessions" aria-label="Permalink to &quot;Delegating to other sessions&quot;">​</a></h2><p>An agent can start and drive other sessions, the way Claude Code drives its subagents:</p><table tabindex="0"><thead><tr><th>MCP tool</th><th>Does</th></tr></thead><tbody><tr><td><code>session_start</code></td><td>Starts a headless ORC chat with a prompt and returns its <code>session_id</code> immediately</td></tr><tr><td><code>session_send</code></td><td>Messages it: <code>queue</code>, <code>steer</code> or <code>interrupt</code></td></tr><tr><td><code>session_status</code> / <code>session_list</code></td><td>Status (<code>queued</code>, <code>running</code>, <code>waiting</code>, <code>idle</code>, <code>failed</code>, <code>stopped</code>), last reply, queue, parent and children</td></tr><tr><td><code>session_wait</code></td><td>Blocks until it stops running, waits for a human, or replies (<code>until: message</code>); <code>session_ids</code> with <code>mode: all</code> or <code>any</code> waits on several children</td></tr><tr><td><code>session_stop</code></td><td>Stops its current turn and, by default (<code>cascade</code>), every session it started; queued children are cancelled; messages still queued for a stopped session are cancelled, and messages sent after the stop deliver normally; sessions stay resumable</td></tr></tbody></table><p><code>session_start</code> takes <code>workspace</code>:</p><table tabindex="0"><thead><tr><th><code>workspace</code></th><th>Same project</th><th>Another project (<code>project</code>)</th></tr></thead><tbody><tr><td><code>same</code> (default)</td><td>The caller&#39;s folder, sharing uncommitted edits</td><td>Refused</td></tr><tr><td><code>worktree</code></td><td>A new git worktree under <code>.orc/worktrees/</code> on a new branch cut from the caller&#39;s committed HEAD (uncommitted edits stay behind)</td><td>A new worktree of that project&#39;s checkout</td></tr><tr><td><code>project</code></td><td>The project&#39;s main checkout</td><td>That project&#39;s main checkout</td></tr></tbody></table><p>Another project must be inside the caller&#39;s MCP project scope.</p><p>When all four chat workers are busy, <code>session_start</code> still returns at once: the child is <code>queued</code> and starts when a worker frees, even across an ORC restart.</p><p>With <code>notify</code> (default on), ORC tells the parent when the child finishes, fails, is stopped or waits for a human. If the parent is mid-turn on an agent with native steering (Claude through the Agent SDK, Pi, Codex) the note is steered into that turn; otherwise it is queued for the parent&#39;s next safe point, or starts the parent&#39;s next chat turn when it is idle. Each note starts with a header line, <code>[orc child-session id=&lt;id&gt; outcome=&lt;outcome&gt;]</code>, so the parent can tell it from human text. The same delivery path carries human messages and channel relays.</p><p>Guardrails:</p><ul><li>Only a session&#39;s parent, or an ancestor of the parent, can <code>steer</code>, <code>interrupt</code> or stop it. Any other session can only <code>queue</code>.</li><li>A child inherits its parent chat&#39;s permission mode, agent options and tool allowlist; a child of any other session starts in the default permission mode. A child&#39;s permission prompt or question goes to a human, never to the parent.</li><li>A child&#39;s notifications to its parent count toward the 20-messages-per-hour cap for that pair.</li><li>A chain of started sessions stops at three levels, and a session can start at most ten sessions an hour.</li></ul><p>Chat and the session detail show the lineage: <strong>Started by</strong> links the parent, and <strong>Started N sessions</strong> lists the children, including the worker sessions of tasks the agent created with <code>task_create</code>.</p><p><img src="`+r+'" alt="Lineage on a parent chat"></p><p><a href="/orc/screens/session-lineage-phone.png">Phone layout of a child chat</a></p>',42)])])}const v=s(d,[["render",c]]);export{f as __pageData,v as default};
